public class Main {
    public static void main(String[] args) {
        int balance = 100;
        int years = 0;
        while (true) {
            if (balance >= 5000) {
                break;
            }
            balance *= 2;
            years++;
        }
        System.out.println("Years to reach 5000: " + years);
        System.out.println("Final balance: " + balance);
    }
}
